-- =============================================================================
-- V25: catalogo de habilidades (glosario N1-N4 2026) y evaluacion de habilidades por drivers (C1).
--  habilidades_catalogo        : GLOBAL (sin club_id). Cada fila es una habilidad distinta del glosario.
--  deportista_habilidades      : por club. Estado actual de cada deportista en cada habilidad evaluada.
--  evaluaciones_habilidad      : por club. Cada evaluacion (fecha, evaluador, puntaje) de una habilidad.
--  evaluacion_habilidad_driver : por club. Deduccion (0-3) de cada driver aplicado en esa evaluacion.
-- Los drivers (Flyer, Bases/Spotters, Transiciones, Aproximacion, ...) son fijos por categoria y viven en codigo.
-- Idempotente.
-- =============================================================================

CREATE TABLE IF NOT EXISTS habilidades_catalogo (
  id         INT AUTO_INCREMENT PRIMARY KEY,
  codigo     VARCHAR(40)  NOT NULL,
  nivel      VARCHAR(10)  NOT NULL,
  categoria  VARCHAR(30)  NOT NULL,
  estilo     VARCHAR(20)  NULL,
  tier       VARCHAR(12)  NULL,
  nombre     VARCHAR(300) NOT NULL,
  nombre_en  VARCHAR(300) NULL,
  activo     BIT(1)       NOT NULL DEFAULT b'1',
  UNIQUE KEY uk_habilidades_codigo (codigo),
  KEY idx_habilidades_nivel (nivel, categoria)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS deportista_habilidades (
  id                INT AUTO_INCREMENT PRIMARY KEY,
  club_id           INT NOT NULL,
  deportista_id     INT NOT NULL,
  habilidad_id      INT NOT NULL,
  estado            VARCHAR(15)   NOT NULL,
  ultimo_puntaje    DECIMAL(4,1)  NOT NULL,
  mejor_puntaje     DECIMAL(4,1)  NOT NULL,
  fecha_ultima      DATE          NOT NULL,
  total_evaluaciones INT          NOT NULL,
  UNIQUE KEY uk_dep_habilidad (club_id, deportista_id, habilidad_id),
  CONSTRAINT fk_dh_club FOREIGN KEY (club_id) REFERENCES clubes (id),
  CONSTRAINT fk_dh_deportista FOREIGN KEY (deportista_id) REFERENCES deportistas (id),
  CONSTRAINT fk_dh_habilidad FOREIGN KEY (habilidad_id) REFERENCES habilidades_catalogo (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS evaluaciones_habilidad (
  id                 INT AUTO_INCREMENT PRIMARY KEY,
  club_id            INT NOT NULL,
  deportista_id      INT NOT NULL,
  habilidad_id       INT NOT NULL,
  fecha              DATE NOT NULL,
  usuario_id         INT NULL,
  valor_inicial      DECIMAL(4,1) NOT NULL,
  total_deducciones  DECIMAL(4,1) NOT NULL,
  puntaje            DECIMAL(4,1) NOT NULL,
  observaciones      VARCHAR(500) NULL,
  KEY idx_eh_deportista (club_id, deportista_id, fecha),
  KEY idx_eh_habilidad (habilidad_id),
  CONSTRAINT fk_eh_club FOREIGN KEY (club_id) REFERENCES clubes (id),
  CONSTRAINT fk_eh_deportista FOREIGN KEY (deportista_id) REFERENCES deportistas (id),
  CONSTRAINT fk_eh_habilidad FOREIGN KEY (habilidad_id) REFERENCES habilidades_catalogo (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS evaluacion_habilidad_driver (
  id                      INT AUTO_INCREMENT PRIMARY KEY,
  club_id                 INT NOT NULL,
  evaluacion_habilidad_id INT NOT NULL,
  nombre_driver           VARCHAR(50) NOT NULL,
  nivel_deduccion         INT NOT NULL,
  CONSTRAINT fk_ehd_club FOREIGN KEY (club_id) REFERENCES clubes (id),
  CONSTRAINT fk_ehd_eval FOREIGN KEY (evaluacion_habilidad_id) REFERENCES evaluaciones_habilidad (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Catalogo de habilidades N1-N4 (glosario 2026). Generado del PDF; revisar por el director tecnico.
